"""Scene exploration on the static snapshot: stable work mapping, zoom, mobile, contrast, image failures."""
import os,sys,json,math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'work/python-deps'))
from playwright.sync_api import sync_playwright,expect
expect.set_options(timeout=15000)
snapshot=json.loads((ROOT/'apps/web/public/competition/manifest.json').read_text(encoding='utf-8'));checks=[];errors=[]
def passed(s):checks.append(s);print('PASS:',s,flush=True)
with sync_playwright()as p:
 b=p.chromium.launch(headless=True,channel='chrome'if os.name=='nt'else None);page=b.new_page(viewport={'width':1600,'height':1050},reduced_motion='reduce');page.on('pageerror',lambda e:errors.append(e.message));page.goto('http://127.0.0.1:5193/',wait_until='networkidle');expect(page.locator('.cloud-universe-node')).to_have_count(10);page.locator('[data-planet-id="demo-1"]').click();expect(page.locator('.scene-saved-background')).to_have_attribute('src','./competition/case-1-interior.webp');expect(page.locator('.scene-growth')).to_have_count(5);assert page.locator('.explorer-viewport').bounding_box()['height']>500;expect(page.locator('.competition-work-grid')).to_have_count(0)
 expected=[w['id']for w in snapshot['students'][0]['works']];assert page.locator('.scene-growth').evaluate_all('(a)=>a.map(e=>e.dataset.workId)')==expected;passed('clicking a student planet enters its saved backdrop with five uniquely mapped scene elements, without a card grid')
 page.get_by_role('button',name='放大场景',exact=True).click();page.get_by_role('button',name='放大场景',exact=True).click();camera=page.locator('.explorer-world').get_attribute('style');first=page.locator('.scene-growth').first;first.focus();first.press('Enter');d=page.get_by_role('dialog',name='比赛作品展示');expect(d).to_contain_text(snapshot['students'][0]['works'][0]['title']);expect(d.get_by_role('region',name='同学互动')).to_be_visible();expect(d).to_contain_text('只读展示快照');d.get_by_role('button',name='放大作品图片',exact=True).click();expect(d.locator('.work-image-button')).to_have_class('work-image-button zoomed');page.screenshot(path=str(ROOT/'outputs/exploration-static-detail.png'));d.get_by_role('button',name='关闭作品',exact=True).click();assert page.locator('.explorer-world').get_attribute('style')==camera;passed('keyboard opens the right work; image zoom, teacher suggestion and peer snapshot remain readable; closing retains scene zoom')
 page.get_by_role('button',name='还原视野',exact=True).click();page.screenshot(path=str(ROOT/'outputs/exploration-static-scene.png'));page.get_by_role('button',name='演示学生 02',exact=True).click();expect(page.locator('.scene-saved-background')).to_have_attribute('src','./competition/case-2-interior.webp');ids2=page.locator('.scene-growth').evaluate_all('(a)=>a.map(e=>e.dataset.workId)');assert not set(expected)&set(ids2);positions=page.locator('.scene-growth').evaluate_all('(a)=>a.map(e=>[e.style.left,e.style.top])');page.reload(wait_until='networkidle');page.locator('[data-planet-id="demo-2"]').click();assert page.locator('.scene-growth').evaluate_all('(a)=>a.map(e=>[e.style.left,e.style.top])')==positions;passed('different students have separate backdrops and work IDs; saved relative placements survive reload')
 page.route('**/case-3-interior.webp*',lambda r:r.fulfill(status=503,body='controlled'));page.get_by_role('button',name='演示学生 03',exact=True).click();expect(page.get_by_text('内部背景暂时无法读取，作品元素仍可打开。',exact=True)).to_be_visible();page.unroute('**/case-3-interior.webp*');page.get_by_role('button',name='重新读取背景',exact=True).click();page.wait_for_function("()=>document.querySelector('.scene-saved-background').complete&&document.querySelector('.scene-saved-background').naturalWidth>0")
 page.route('**/student-3-work-1.webp*',lambda r:r.fulfill(status=503,body='controlled'));page.locator('.scene-growth').first.click();d=page.get_by_role('dialog',name='比赛作品展示');expect(d.get_by_text('作品图片读取失败。',exact=True)).to_be_visible();page.unroute('**/student-3-work-1.webp*');d.get_by_role('button',name='重新读取作品图片',exact=True).click();expect(d.get_by_role('img')).to_be_visible();d.get_by_role('button',name='关闭作品',exact=True).click();passed('controlled backdrop and work-image failures show retry controls and recover without losing the scene')
 page.get_by_role('button',name='色彩的奥秘',exact=True).click();expect(page.get_by_role('heading',name='色彩的奥秘',exact=True)).to_be_visible();expect(page.get_by_text('每一种颜色，都可能开启一种不同的感受。探索色彩的冷暖、明暗与搭配，为你的星球找到独特的表达。',exact=True).first).to_be_visible();passed('the renamed color knowledge entrance uses the shared introductory copy')
 mobile=b.new_page(viewport={'width':390,'height':844},reduced_motion='reduce');mobile.on('pageerror',lambda e:errors.append(e.message));mobile.goto('http://127.0.0.1:5193/',wait_until='networkidle');mobile.locator('[data-planet-id="demo-1"]').click();assert mobile.locator('body').evaluate('(e)=>e.scrollWidth')<=391
 for e in mobile.locator('.scene-growth').all():r=e.bounding_box();assert r['width']>=44 and r['height']>=44
 mobile.locator('.scene-growth').last.click();expect(mobile.get_by_role('dialog',name='比赛作品展示')).to_contain_text(snapshot['students'][0]['works'][-1]['title']);mobile.screenshot(path=str(ROOT/'outputs/exploration-static-mobile.png'));passed('390px mobile layout has no horizontal overflow and every scene entry has a touch target larger than 44px')
 assert not errors,errors;b.close()
(ROOT/'outputs/exploration-static-acceptance.json').write_text(json.dumps({'status':'passed','mode':'static read-only snapshot; no live write claims','checks':checks,'pageErrors':errors},ensure_ascii=False,indent=2),encoding='utf-8')
